import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { BlogPost } from '../types';
import { blogPosts, blogCategories } from '../constants';
import BlogPostCard from '../components/BlogPostCard';

const BlogPage: React.FC = () => {
  const [selectedCategory, setSelectedCategory] = useState<string>('Todos');

  const filteredPosts = selectedCategory === 'Todos' 
    ? blogPosts 
    : blogPosts.filter(post => post.category === selectedCategory);

  return (
    <div className="bg-white">
      <div className="bg-light-gray">
        <div className="container mx-auto px-4 sm:px-6 lg:px-8 py-16 text-center">
          <h1 className="text-4xl md:text-5xl font-extrabold text-base-blue">Blog Rabello ADS</h1>
          <p className="mt-4 max-w-2xl mx-auto text-lg text-gray-600">
            Conhecimento para iniciantes, profissionais e empreendedores. Dicas práticas, tutoriais e análises para ajudar você a crescer com método.
          </p>
        </div>
      </div>

      <div className="container mx-auto px-4 sm:px-6 lg:px-8 py-16">
        {/* Category Filters */}
        <div className="flex justify-center flex-wrap gap-2 mb-12">
          {['Todos', ...blogCategories].map(category => (
            <button
              key={category}
              onClick={() => setSelectedCategory(category)}
              className={`px-4 py-2 rounded-full text-sm font-semibold transition-colors duration-300 ${
                selectedCategory === category
                  ? 'bg-base-blue text-white'
                  : 'bg-breathing-gray text-gray-700 hover:bg-gray-300'
              }`}
            >
              {category}
            </button>
          ))}
        </div>

        {/* Blog Posts Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {filteredPosts.map(post => (
            <BlogPostCard key={post.id} post={post} />
          ))}
        </div>

         {/* Newsletter CTA */}
        <div className="mt-20 max-w-3xl mx-auto text-center bg-base-blue text-white p-8 rounded-lg">
          <h2 className="text-2xl font-bold">Fique por dentro das novidades</h2>
          <p className="mt-2">Assine nossa newsletter para receber novos artigos e dicas exclusivas diretamente no seu e-mail.</p>
          <form className="mt-6 flex flex-col sm:flex-row gap-4 justify-center">
            <input 
              type="email" 
              placeholder="Seu melhor e-mail" 
              className="w-full sm:w-auto flex-grow px-4 py-3 rounded-md text-gray-800 focus:outline-none focus:ring-2 focus:ring-consulting-amber"
            />
            <button 
              type="submit"
              className="bg-education-green text-white font-semibold py-3 px-6 rounded-md hover:bg-opacity-90 transition-colors"
            >
              Assinar
            </button>
          </form>
        </div>

      </div>
    </div>
  );
};

export default BlogPage;

import React, { useState } from 'react';

const ContactPage: React.FC = () => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    message: '',
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    // Here you would typically handle form submission, e.g., send to an API
    console.log('Form data submitted:', formData);
    alert('Mensagem enviada com sucesso! Entraremos em contato em breve.');
    setFormData({ name: '', email: '', message: '' });
  };

  return (
    <div className="bg-white py-16 md:py-24">
      <div className="container mx-auto px-4 sm:px-6 lg:px-8">
        <div className="max-w-3xl mx-auto text-center">
          <h1 className="text-4xl md:text-5xl font-extrabold text-base-blue">Entre em Contato</h1>
          <p className="mt-4 text-lg text-gray-600">
            Tem alguma dúvida ou quer discutir um projeto? Preencha o formulário abaixo ou, se preferir, entre em contato pelo WhatsApp.
          </p>
        </div>

        <div className="mt-12 max-w-xl mx-auto">
          <form onSubmit={handleSubmit} className="space-y-6">
            <div>
              <label htmlFor="name" className="block text-sm font-medium text-gray-700">Nome</label>
              <input
                type="text"
                name="name"
                id="name"
                value={formData.name}
                onChange={handleChange}
                required
                className="mt-1 block w-full px-4 py-3 border border-gray-300 rounded-md shadow-sm focus:ring-base-blue focus:border-base-blue"
              />
            </div>
            <div>
              <label htmlFor="email" className="block text-sm font-medium text-gray-700">Email</label>
              <input
                type="email"
                name="email"
                id="email"
                value={formData.email}
                onChange={handleChange}
                required
                className="mt-1 block w-full px-4 py-3 border border-gray-300 rounded-md shadow-sm focus:ring-base-blue focus:border-base-blue"
              />
            </div>
            <div>
              <label htmlFor="message" className="block text-sm font-medium text-gray-700">Sua mensagem</label>
              <textarea
                name="message"
                id="message"
                rows={4}
                value={formData.message}
                onChange={handleChange}
                required
                className="mt-1 block w-full px-4 py-3 border border-gray-300 rounded-md shadow-sm focus:ring-base-blue focus:border-base-blue"
              ></textarea>
            </div>
            <div className="text-center">
              <button
                type="submit"
                className="w-full bg-base-blue text-white font-semibold py-3 px-8 rounded-lg shadow-md hover:bg-opacity-90 transition-colors duration-300"
              >
                Enviar Mensagem
              </button>
              <p className="mt-4 text-xs text-gray-500">
                Seus dados são utilizados apenas para contato e análise do seu cenário. Respeitamos sua privacidade.
              </p>
            </div>
          </form>

          <div className="mt-12 text-center border-t pt-8">
            <h3 className="text-lg font-semibold text-gray-800">Prefere uma conversa mais direta?</h3>
            <a 
              href="https://wa.me/5511999999999" // Replace with actual WhatsApp number
              target="_blank" 
              rel="noopener noreferrer"
              className="mt-4 inline-flex items-center gap-2 bg-education-green text-white font-semibold py-3 px-6 rounded-lg shadow-md hover:bg-opacity-90 transition-colors duration-300"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                <path d="M10.25 1.25a8.75 8.75 0 100 17.5 8.75 8.75 0 000-17.5zm-2.02 12.37a.75.75 0 01-1.06 1.06l-2.5-2.5a.75.75 0 010-1.06l2.5-2.5a.75.75 0 111.06 1.06L7.31 10l1.92 1.92a.75.75 0 010 1.061zM14.53 11.03a.75.75 0 010-1.06l-2.5-2.5a.75.75 0 011.06-1.06l2.5 2.5a.75.75 0 010 1.06l-2.5 2.5a.75.75 0 11-1.06-1.06l1.92-1.92z"/>
              </svg>
              Chamar no WhatsApp
            </a>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ContactPage;

export interface BlogPost {
  id: number;
  title: string;
  excerpt: string;
  imageUrl: string;
  category: string;
  date: string;
  author: string;
  slug: string;
}

import React from 'react';
import { Link } from 'react-router-dom';
import { BlogPost } from '../types';

interface BlogPostCardProps {
  post: BlogPost;
}

const BlogPostCard: React.FC<BlogPostCardProps> = ({ post }) => {
  const categoryColorMap: { [key: string]: string } = {
    'Iniciantes': 'bg-blue-100 text-blue-800',
    'Empreendedores': 'bg-consulting-amber bg-opacity-20 text-consulting-amber',
    'Tutoriais': 'bg-education-green bg-opacity-20 text-green-800',
    'Análises': 'bg-red-100 text-red-800',
  };

  const categoryClasses = categoryColorMap[post.category] || 'bg-gray-100 text-gray-800';

  return (
    <div className="bg-white rounded-lg shadow-md overflow-hidden flex flex-col group transition-all duration-300 hover:shadow-xl">
      <Link to={`/blog/${post.slug}`} className="block overflow-hidden">
        <img src={post.imageUrl} alt={post.title} className="w-full h-48 object-cover group-hover:scale-105 transition-transform duration-300" />
      </Link>
      <div className="p-6 flex flex-col flex-grow">
        <div className="flex justify-between items-center mb-2">
            <span className={`inline-block px-3 py-1 text-xs font-semibold rounded-full ${categoryClasses}`}>
                {post.category}
            </span>
            <p className="text-sm text-gray-500">{post.date}</p>
        </div>
        <h3 className="text-xl font-bold text-base-blue mt-2">
          <Link to={`/blog/${post.slug}`} className="hover:text-consulting-amber transition-colors duration-200">
            {post.title}
          </Link>
        </h3>
        <p className="mt-2 text-gray-600 flex-grow">{post.excerpt}</p>
        <div className="mt-4">
          <Link to={`/blog/${post.slug}`} className="font-semibold text-base-blue hover:text-consulting-amber transition-colors duration-200">
            Ler mais &rarr;
          </Link>
        </div>
      </div>
    </div>
  );
};

export default BlogPostCard;

import { useEffect } from 'react';
import { useLocation } from 'react-router-dom';

const ScrollToTop = () => {
  const { pathname } = useLocation();

  useEffect(() => {
    window.scrollTo(0, 0);
  }, [pathname]);

  return null;
};

export default ScrollToTop;

